n=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# Search for inverted repeats: for each pair of positions i<j with same length k, revcomp match
def find_irs(seq, minlen=10, maxlen=60, maxgap=3000):
    hits=[]
    n=len(seq)
    for k in range(minlen, maxlen+1):
        seen={}
        for i in range(0, n-k+1):
            sub = seq[i:i+k]
            key = rc(sub)
            if key in seen:
                for j in seen[key]:
                    hits.append((k, j, i))  # j < i
            seen.setdefault(sub,[]).append(i)
    return hits

# more efficient: check all pairs of positions with fixed k using dict
def find_irs2(seq, minlen=12, maxlen=40):
    n=len(seq)
    res=[]
    for k in range(minlen, maxlen+1):
        d={}
        for i in range(n-k+1):
            s=seq[i:i+k]
            d.setdefault(s,[]).append(i)
        for i in range(n-k+1):
            s=seq[i:i+k]
            t=rc(s)
            if t in d:
                for j in d[t]:
                    if j>i:
                        res.append((k,i,j))
    return res

irs = find_irs2(seq, 12, 40)
# filter by arm length and gap
irs.sort(key=lambda x:-x[0])
for k,i,j in irs[:40]:
    print("arm=%d left=%d right=%d (1-based %d/%d) gap=%d" % (k,i,j,i+1,j+1,j-(i+k)))
print("total IR pairs:", len(irs))
