n=len(seq)
ctab=str.maketrans("ACGT","TGCA")
comp = seq.translate(ctab)
comp = "".join(comp)  # comp[i] = complement of seq[i]

# Inverted repeat search: anti-diagonals i+j=c, seq[i]==comp[j]
runs=[]
for c in range(4, 2*n-4):
    i0 = max(0, c-(n-1))
    i1 = min(n-1, c)
    if i1-i0 < 11: continue
    cur=0; start=None
    for i in range(i0, i1+1):
        j = c-i
        if j<=i: break
        if seq[i]==comp[j]:
            if start is None: start=i
            cur+=1
        else:
            if cur>=12:
                runs.append((cur,start,c-start))
            cur=0; start=None
    if cur>=12:
        runs.append((cur,start,c-start))
runs.sort(key=lambda x:-x[0])
print("Longest inverted-repeat arms (allow no mismatch within arm):")
for L,p,q in runs[:15]:
    print("  arm=%d  left %d..%d  right %d..%d  gap=%d  mm=0" % (L,p+1,p+L,q+1,q+L,q-(p+L)))
print("total runs>=12:", len(runs))

# Direct repeats: diagonals j-i=d
runs2=[]
for d in range(1, n-11):
    cur=0; start=None
    for i in range(0, n-d):
        j=i+d
        if seq[i]==seq[j]:
            if start is None: start=i
            cur+=1
        else:
            if cur>=12: runs2.append((cur,start,d))
            cur=0; start=None
    if cur>=12: runs2.append((cur,start,d))
runs2.sort(key=lambda x:-x[0])
