lines = open("region.fasta").read().split("\n")
seq = "".join(l.strip() for l in lines[1:] if l.strip())
n=len(seq)
ct=str.maketrans("ACGT","TGCA")
def comp_char(c): return c.translate(ct)

# Correct mismatch-tolerant IR search.
# arms: left = p..p+L-1, right = q..q+L-1, with seq[p+k] == comp(seq[q+L-1-k])
# seed: 10-mer at left-arm start p; require seq[p:p+10] == rc(seq[q:q+10])
seed=10
idx={}
for i in range(n-seed+1):
    idx.setdefault(seq[i:i+seed],[]).append(i)
def rcstr(s): return s.translate(ct)[::-1]

best=[]
for p in range(n-seed+1):
    key = rcstr(seq[p:p+seed])
    # allow 1 mismatch in seed
    variants={key}
    for k in range(seed):
        for b in "ACGT":
            if b!=key[k]:
                variants.add(key[:k]+b+key[k+1:])
    found=set()
    for v in variants:
        for q in idx.get(v,[]):
            if q-seed>=p+seed:  # need arms to not overlap
                found.add(q)
    for q in found:
        # extend outward with mismatches allowed (stop at first mismatch block of 2)
        L=seed; mm=0
        while p+L < q and q-1 >= 0:
            if seq[p+L]==comp_char(seq[q-1]):
                L+=1
            else:
                break
        # count seed mismatches
        seedmm = sum(1 for k in range(seed) if seq[p+k]!=comp_char(seq[q+seed-1-k]))
        best.append((L, seedmm, p, q))
best.sort(key=lambda x:-x[0])
print("Top IRs (arm>=14, allowing up to 2 mismatches):")
shown=0
for L,mm,p,q in best:
    if L>=14 and mm<=2:
        print("  arm=%d seedmm=%d left=%d..%d right=%d..%d gap=%d" % (L,mm,p+1,p+L,q+1,q+L,q-(p+L)))
        shown+=1
        if shown>=25: break
print("total candidates arm>=14 with <=2mm:", sum(1 for L,mm,p,q in best if L>=14 and mm<=2))
print("total candidates arm>=12 with <=2mm:", sum(1 for L,mm,p,q in best if L>=12 and mm<=2))
print("max arm found:", best[0] if best else None)
